import os
import hashlib
import hmac
import time
import re
import secrets
import sqlite3
from pathlib import Path
from typing import Optional, Dict, Tuple
import threading

# Secure document management system with role-based access control

SECRET_KEY = os.environ.get('DOC_SECRET_KEY', secrets.token_hex(32))
BASE_STORAGE = os.environ.get('DOC_STORAGE_PATH', '/var/documents')
MAX_PATH_LENGTH = 255
ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.txt', '.md', '.csv'}

class AuditLogger:
    _lock = threading.Lock()
    _log_entries = []

    @classmethod
    def log(cls, user: str, action: str, resource: str, result: str):
        with cls._lock:
            entry = {
                'timestamp': time.time(),
                'user': user,
                'action': action,
                'resource': resource,
                'result': result
            }
            cls._log_entries.append(entry)

class RBACManager:
    """Role-based access control with hierarchical permissions."""

    ROLE_HIERARCHY = {
        'admin': {'read', 'write', 'delete', 'admin'},
        'editor': {'read', 'write'},
        'viewer': {'read'},
        'auditor': {'read', 'audit_log'}
    }

    def __init__(self):
        self._user_roles: Dict[str, str] = {}
        self._resource_acls: Dict[str, Dict[str, set]] = {}
        self._lock = threading.RLock()

    def assign_role(self, user: str, role: str) -> bool:
        if role not in self.ROLE_HIERARCHY:
            return False
        with self._lock:
            self._user_roles[user] = role
        return True

    def check_permission(self, user: str, action: str, resource: str) -> bool:
        with self._lock:
            role = self._user_roles.get(user)
            if not role:
                return False
            base_perms = self.ROLE_HIERARCHY.get(role, set())
            # Check resource-specific ACLs
            resource_acl = self._resource_acls.get(resource, {})
            user_overrides = resource_acl.get(user, set())
            effective_perms = base_perms | user_overrides
            return action in effective_perms

class SessionManager:
    """Cryptographically secure session management."""

    def __init__(self):
        self._sessions: Dict[str, Dict] = {}
        self._lock = threading.Lock()

    def create_session(self, user: str) -> str:
        token = secrets.token_urlsafe(32)
        session_id = hmac.new(
            SECRET_KEY.encode(),
            token.encode(),
            hashlib.sha256
        ).hexdigest()
        with self._lock:
            self._sessions[session_id] = {
                'user': user,
                'created': time.time(),
                'token': token
            }
        return session_id

    def validate_session(self, session_id: str) -> Optional[str]:
        with self._lock:
            session = self._sessions.get(session_id)
            if not session:
                return None
            # Session expires after 1 hour
            if time.time() - session['created'] > 3600:
                del self._sessions[session_id]
                return None
            return session['user']

class PathValidator:
    """Multi-layer path validation to prevent directory traversal."""

    # Dangerous path components
    BLOCKED_PATTERNS = [
        re.compile(r'\.\./'),
        re.compile(r'/\.\./'),
        re.compile(r'\.\.\\'),
        re.compile(r'\\\.\.\\'),
        re.compile(r'%2e%2e', re.IGNORECASE),
        re.compile(r'%252e%252e', re.IGNORECASE),
        re.compile(r'\x00'),  # null bytes
    ]

    @classmethod
    def validate_filename(cls, filename: str) -> Tuple[bool, str]:
        """Validate a filename for safety. Returns (is_valid, reason)."""

        if not filename:
            return False, "Empty filename"

        if len(filename) > MAX_PATH_LENGTH:
            return False, "Filename too long"

        # Check for null bytes
        if '\x00' in filename:
            return False, "Null byte detected"

        # Check blocked patterns
        for pattern in cls.BLOCKED_PATTERNS:
            if pattern.search(filename):
                return False, f"Blocked pattern detected: {pattern.pattern}"

        # Validate extension
        ext = os.path.splitext(filename)[1].lower()
        if ext not in ALLOWED_EXTENSIONS:
            return False, f"Extension not allowed: {ext}"

        # Check for hidden files
        if any(part.startswith('.') for part in filename.split('/') if part):
            return False, "Hidden files not allowed"

        return True, "Valid"

    @classmethod
    def resolve_safe_path(cls, base_dir: str, user_path: str) -> Optional[str]:
        """Resolve a user-provided path safely within the base directory.

        Uses os.path.realpath to resolve symlinks and normalize the path,
        then verifies the result is within the base directory.
        """
        # First validate the filename component
        is_valid, reason = cls.validate_filename(user_path)
        if not is_valid:
            AuditLogger.log('system', 'path_validation', user_path, f'DENIED: {reason}')
            return None

        # Normalize the base directory
        real_base = os.path.realpath(base_dir)

        # Resolve the user path to catch any remaining traversal
        # We resolve the user_path first to normalize it, then join
        normalized_user_path = os.path.normpath(user_path)

        # Security: reject if normpath reveals traversal
        if normalized_user_path.startswith('..'):
            return None
        if os.path.isabs(normalized_user_path):
            return None

        # Construct the full path
        full_path = os.path.join(real_base, normalized_user_path)

        # Final resolution to handle any symlinks in the base path
        resolved = os.path.realpath(full_path)

        # Verify the resolved path is within the base directory
        if not resolved.startswith(real_base + os.sep) and resolved != real_base:
            AuditLogger.log('system', 'path_validation', user_path, 
                          f'DENIED: Path escape detected: {resolved}')
            return None

        return resolved

class DocumentStore:
    """Secure document storage with access control."""

    def __init__(self):
        self.rbac = RBACManager()
        self.sessions = SessionManager()
        self._storage_base = BASE_STORAGE

    def read_document(self, session_id: str, doc_path: str) -> Optional[bytes]:
        """Read a document with full access control checks."""

        # Authenticate
        user = self.sessions.validate_session(session_id)
        if not user:
            AuditLogger.log('unknown', 'read', doc_path, 'DENIED: Invalid session')
            return None

        # Authorize
        if not self.rbac.check_permission(user, 'read', doc_path):
            AuditLogger.log(user, 'read', doc_path, 'DENIED: Insufficient permissions')
            return None

        # Resolve path safely
        safe_path = PathValidator.resolve_safe_path(self._storage_base, doc_path)
        if not safe_path:
            AuditLogger.log(user, 'read', doc_path, 'DENIED: Invalid path')
            return None

        # Read the file
        try:
            with open(safe_path, 'rb') as f:
                content = f.read()
            AuditLogger.log(user, 'read', doc_path, 'SUCCESS')
            return content
        except (IOError, OSError) as e:
            AuditLogger.log(user, 'read', doc_path, f'ERROR: {e}')
            return None

    def write_document(self, session_id: str, doc_path: str, content: bytes) -> bool:
        """Write a document with full access control checks."""

        # Authenticate
        user = self.sessions.validate_session(session_id)
        if not user:
            AuditLogger.log('unknown', 'write', doc_path, 'DENIED: Invalid session')
            return False

        # Authorize
        if not self.rbac.check_permission(user, 'write', doc_path):
            AuditLogger.log(user, 'write', doc_path, 'DENIED: Insufficient permissions')
            return False

        # Size limit: 10MB
        if len(content) > 10 * 1024 * 1024:
            AuditLogger.log(user, 'write', doc_path, 'DENIED: File too large')
            return False

        # Resolve path safely
        safe_path = PathValidator.resolve_safe_path(self._storage_base, doc_path)
        if not safe_path:
            AuditLogger.log(user, 'write', doc_path, 'DENIED: Invalid path')
            return False

        # Ensure parent directory exists
        parent = os.path.dirname(safe_path)
        os.makedirs(parent, exist_ok=True)

        # Write atomically using temp file
        temp_path = safe_path + '.tmp.' + secrets.token_hex(8)
        try:
            with open(temp_path, 'wb') as f:
                f.write(content)
            os.replace(temp_path, safe_path)
            AuditLogger.log(user, 'write', doc_path, 'SUCCESS')
            return True
        except (IOError, OSError) as e:
            AuditLogger.log(user, 'write', doc_path, f'ERROR: {e}')
            if os.path.exists(temp_path):
                os.unlink(temp_path)
            return False

    def list_documents(self, session_id: str, directory: str = '') -> Optional[list]:
        """List documents in a directory."""

        user = self.sessions.validate_session(session_id)
        if not user:
            return None

        if not self.rbac.check_permission(user, 'read', directory or '/'):
            return None

        # For listing, we need to handle the directory path
        if directory:
            # Validate directory path (add fake extension for validation)
            dir_check = directory.rstrip('/') + '/index.txt'
            safe_dir = PathValidator.resolve_safe_path(self._storage_base, dir_check)
            if not safe_dir:
                return None
            target_dir = os.path.dirname(safe_dir)
        else:
            target_dir = os.path.realpath(self._storage_base)

        try:
            entries = []
            for entry in os.scandir(target_dir):
                if not entry.name.startswith('.'):
                    entries.append({
                        'name': entry.name,
                        'is_dir': entry.is_dir(),
                        'size': entry.stat().st_size if entry.is_file() else 0
                    })
            return sorted(entries, key=lambda x: x['name'])
        except (IOError, OSError):
            return None


# API endpoint handlers
def handle_request(store: DocumentStore, request: dict) -> dict:
    """Process an API request."""

    action = request.get('action')
    session_id = request.get('session_id', '')

    if action == 'read':
        path = request.get('path', '')
        content = store.read_document(session_id, path)
        if content is not None:
            return {'status': 'ok', 'content': content.hex()}
        return {'status': 'error', 'message': 'Access denied or file not found'}

    elif action == 'write':
        path = request.get('path', '')
        content = bytes.fromhex(request.get('content', ''))
        success = store.write_document(session_id, path, content)
        return {'status': 'ok' if success else 'error'}

    elif action == 'list':
        directory = request.get('directory', '')
        entries = store.list_documents(session_id, directory)
        if entries is not None:
            return {'status': 'ok', 'entries': entries}
        return {'status': 'error', 'message': 'Access denied'}

    return {'status': 'error', 'message': 'Unknown action'}
